const RTDetail=(()=>{
 let selected='summary',language='both',lastLead=null;
 const labels={summary:'Summary · 概览',evidence:'Evidence · 证据',analysis:'Analysis · 分析',approach:'Approach · 接洽',files:'Files · 文件',orders:'Orders · 订单'};
 const bi=(zh,en)=>`<div class="bilingual"><div lang="zh-CN">${zh}</div><div lang="en">${en}</div></div>`;
 const textPair=p=>bi(`<p>${esc(p?.zh||'尚未完成本轮分析。')}</p>`,`<p>${esc(p?.en||'Not yet reviewed in this research pass.')}</p>`);
 function evidence(l){const a=l.analysis;return `<h3>证据档案 / Evidence register</h3><p>来源事实、搜索摘要和研究推断分开记录。Source statements do not establish demand for Rainbow Town.</p>${a?`<div class="notice">本轮核查 / Reviewed: ${esc(a.reviewed_at)} · ${esc(a.review_status.zh)} / ${esc(a.review_status.en)}</div>`:''}<h4>本轮发现 / Current research</h4>${(a?.evidence||[]).map((s,i)=>`<article class="source"><span class="tag">E${i+1} · ${esc(s.state)}</span>${anchor(s.url,s.title)}<small>${esc(s.observation_kind||'Short source excerpt')}</small><p>${esc(s.observation)}</p><small>${esc(s.note)}</small><small>Checked ${esc(s.checked_at)}</small></article>`).join('')||'<p>没有本轮新增来源 / No additional source collected in this pass.</p>'}<h4>原始记录 / Original research</h4><p>${esc(l.fact)}</p>${l.sources.map(s=>`<article class="source">${anchor(s.url,s.label)}<small>${esc(reading(s.reading_state))} · ${esc(s.read_at||D.checked_at)}</small><p>${esc(s.note)}</p></article>`).join('')}<h4>全部渠道 / All channel entry points</h4>${Object.entries(l.channels).map(([k,v])=>`<article class="source"><strong>${esc(k)}</strong>${v.map(x=>`<p>${anchor(x.url,k)}<small>${esc(x.evidence_kind)} · Profile links and map searches are not reviewed posts or demand.</small></p>`).join('')}</article>`).join('')}`}
 function analysis(l){const a=l.analysis;if(!a)return textPair();return `<div class="analysis-lead">${a.citation_priority?'<span class="tag">研究判断 / Inference</span>':''}${textPair(a.verdict)}</div><div class="analysis-grid">${a.dimensions.map(d=>`<section><h3>${esc(d.title.zh)} / ${esc(d.title.en)}</h3>${d.kind?`<span class="tag">${esc(({fact:"来源事实 / Source fact",calculation:"计算 / Calculation",inference:"研究判断 / Inference",excerpt:"来源摘录 / Source excerpt",unknown:"尚未确认 / Unconfirmed",record:"档案信息 / Recorded"})[d.kind])}</span>`:""}${textPair(d.body)}${(d.sources||[]).map(x=>`<small class="claim-source">${anchor(x.url,x.title)} · ${esc(x.state)}<br>${esc(x.supports)}</small>`).join("")}${d.evidence_ids?.length?`<small>依据 / Basis: ${d.evidence_ids.map(i=>'E'+i).join(', ')}</small>`:''}</section>`).join('')}</div><p>接洽策略、邮件和 PDF 大纲请见 Approach。 / See Approach for the outreach strategy, email and PDF outline.</p><p class="analysis-disclaimer">分析是基于公开资料的研究判断；人工星级、V0–V3 商业资格和实际合作结果分别记录。Research priority is separate from manual levels, qualification and actual commercial outcomes.</p>`}
 function approach(l){const a=l.approach;if(!a)return textPair({zh:'此对象未纳入本轮 218 条客户候选；暂无接洽方案。',en:'This record is outside this pass’s 218 customer candidates; no approach brief is available.'});const section=(n,z,en,body)=>`<details class="approach-section" ${n===5?"open":""}><summary>${n}. ${z} / ${en}</summary>${n===5?'<div class="stage-steps"><span>1 · 了解背景</span><span>2 · 提供选择</span><span>3 · 轻量邀请</span></div>':""}${body}</details>`;return `${a.outreach_summary?`<section class="approach-overview" aria-label="接洽方向摘要"><h3>接洽方向 / Approach at a glance</h3>${textPair(a.outreach_summary.body)}<div class="overview-sources">${a.outreach_summary.sources.map(x=>anchor(x.url,x.title)).join(" · ")}</div></section>`:""}<div class="notice">中英文接洽方案 · ${esc(a.created_at)} · 草稿，未发送 / Bilingual approach brief · Draft, not sent</div>`+section(1,'证据与客户反馈','Evidence & customer voice',textPair(a.finding)+`<small>机构资料依据 / Organisational sources: ${a.evidence_refs.map(i=>'E'+i).join(', ')} · Evidence 标签可查看 / See Evidence</small>`+textPair(a.feedback.status)+textPair(a.feedback.interpretation)+(a.feedback.sources||[]).map((x,i)=>`<article class="source"><span class="tag">F${i+1} · ${esc(x.state)}</span>${anchor(x.url,x.title)}${textPair(x.note)}</article>`).join(''))+section(2,'痛点与核心需求','Pain points & core needs',a.pains.map(x=>`<article><h4>${esc(x.label.zh)} / ${esc(x.label.en)}</h4>${textPair(x.body)}<small>${esc(x.basis.zh)} / ${esc(x.basis.en)}</small></article>`).join(''))+section(3,'我们能够满足的点','Our potential contribution',a.fit.map(x=>`<article><h4>${esc(x.title.zh)} / ${esc(x.title.en)}</h4>${textPair(x.body)}</article>`).join(''))+section(4,'接洽路线','Approaching sequence',textPair(a.angle)+`<ol>${a.steps.map(x=>`<li><h4>${esc(x.title.zh)} / ${esc(x.title.en)}</h4>${textPair(x.body)}</li>`).join('')}</ol>`+textPair(a.gate))+section(5,'首次邮件','Initial email',textPair(a.email.status)+`<div class="email-actions"><button data-copy-approach="zh">复制中文邮件</button><button data-copy-approach="en">Copy English email</button><span id="approach-copy-status" role="status"></span></div><h4>Subject / 主题</h4>${textPair(a.email.subject)}<div class="email-draft">${emailContent(a.email)}</div>`)+section(6,'PDF 附件大纲','PDF attachment outline',textPair(a.pdf_status)+`<ol>${a.pdf_outline.map(x=>`<li><h4>${esc(x.title.zh)} / ${esc(x.title.en)}</h4>${textPair(x.body)}</li>`).join('')}</ol>`)}
 function emailContent(e){if(!e.paragraphs)return textPair(e.body);const side=lang=>e.paragraphs.map((p,i)=>`<p>${esc(p[lang])}</p>${e.visual&&e.visual.after===i?`<figure><img src="${esc(e.visual.url)}" alt="${esc(e.visual.caption[lang])}" style="width:100%;height:auto"><figcaption>${esc(e.visual.caption[lang])}</figcaption></figure>`:''}`).join('')+`<p>${e.links.map(x=>anchor(x.url,x.label[lang])).join(' · ')}</p>`;return bi(side('zh'),side('en'));}
 function files(l){return `<h3>方案与附件 / Plans & attachments</h3>${l.files?.length?`<div class="file-list">${l.files.map(f=>`<article class="source"><strong>${esc(f.name)}</strong><small>${esc(f.type||'Document')} · ${esc(f.created_at||'Date unknown')} · ${esc(f.status||'Draft')}</small><p>${anchor(f.url,'打开文件 / Open file')}</p>${f.description?`<p>${esc(f.description)}</p>`:''}</article>`).join('')}</div>`:'<div class="empty"><h3>暂无方案文件 / No proposal files yet</h3><p>此线索尚未生成或附加 PDF、报价或合作方案。分析在 Analysis 中查看，邮件与 PDF 大纲在 Approach 中查看。</p><p>No PDF, quotation or proposal has been generated or attached for this lead. Research is in Analysis; email drafts and the PDF outline are in Approach.</p></div>'}`}
 function mount(l){language='both';const root=$('detailbody'),management=root.querySelector('.management'),form=management?.querySelector('form'),title=root.querySelector('h2');if(lastLead&&lastLead!==l.id)state.detailTab='summary';lastLead=l.id;selected=['summary','evidence','analysis','approach','files','orders'].includes(state.detailTab)?state.detailTab:'summary';root.replaceChildren();root.append(title);const nav=document.createElement('div');nav.className='detail-tabs';nav.setAttribute('role','tablist');nav.setAttribute('aria-label','Lead details');nav.innerHTML=Object.entries(labels).filter(([id])=>id!=='orders'||RTCRM.get(l.id).status==='client').map(([id,label])=>`<button role="tab" id="tab-${id}" aria-controls="panel-${id}" data-detail-tab="${id}">${label}</button>`).join('');root.append(nav);const toolbar=document.createElement('div');toolbar.className='analysis-language';toolbar.innerHTML='<span>语言 / Language</span><button data-language="both" aria-pressed="true">中文 + English 对照</button><button data-language="zh" aria-pressed="false">仅中文</button><button data-language="en" aria-pressed="false">English only</button>';root.append(toolbar);
 const summary=document.createElement('section');summary.id='panel-summary';summary.setAttribute('role','tabpanel');summary.setAttribute('aria-labelledby','tab-summary');summary.innerHTML=`<span class="tag">${esc(l.type)}</span><p>${esc(l.address)} · ${esc(dist(l))}</p>${contacts(l)}<h3>机构概览 / Organisation summary</h3>${RTFlow.summary(l)}<button id="edit-profile">编辑基本资料 / Edit profile</button><small>本轮研究 / Research updated: ${esc(l.analysis?.reviewed_at||'Not reviewed in this pass')} · ${esc(l.analysis?.review_status.en||'')}</small><button id="read-full-analysis">查看完整分析 / Read full analysis</button><button id="read-approach" class="approach-entry">接洽邮件与方案 / Email & proposal →</button><h3>照片 / Photos</h3>${photo(l,true)}<h3>线索基本资料 / Lead profile</h3><dl><dt>Sport / 运动</dt><dd>${esc(l.sport)}</dd><dt>Role / 关系</dt><dd>${esc(l.role)}</dd><dt>Location basis / 地址依据</dt><dd>${esc(l.locationRole)}<small>${esc(l.geo_evidence)}</small></dd><dt>Qualification / 资格</dt><dd>${l.role==='Competition reference'?'竞争参考 / Competition reference':RTCRM.get(l.id).status==='client'?'已合作 · 手工标记 / Client · manually marked':'待核实 / Unqualified'}</dd></dl><details class="workflow-editor"><summary>我的评级、评注与跟进 / My workflow</summary></details>`;if(form){const host=summary.querySelector('.workflow-editor');host.open=true;host.append(form)}if(RTCRM.get(l.id).status==='client')summary.insertAdjacentHTML('beforeend',RTFlow.schedules(l));root.append(summary);
 for(const id of ['evidence','analysis','approach','files',...(RTCRM.get(l.id).status==='client'?['orders']:[])]){const panel=document.createElement('section');panel.id='panel-'+id;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby','tab-'+id);panel.innerHTML=id==='evidence'?evidence(l):id==='analysis'?analysis(l):id==='approach'?approach(l):id==='orders'?'<p>Loading orders…</p>':files(l);root.append(panel)}
 function choose(tab,focus=false){selected=tab;state.detailTab=tab;const u=new URL(location.href);u.searchParams.set('detailTab',tab);history.replaceState(null,'',u);nav.querySelectorAll('button').forEach(b=>{const yes=b.dataset.detailTab===tab;b.setAttribute('aria-selected',String(yes));b.tabIndex=yes?0:-1;if(yes&&focus)b.focus()});root.querySelectorAll('[role="tabpanel"]').forEach(p=>p.hidden=p.id!=='panel-'+tab);toolbar.hidden=!['summary','analysis','approach'].includes(tab);RTPhotos.bind(leads)}
 nav.querySelectorAll('button').forEach((b,i)=>{b.onclick=()=>choose(b.dataset.detailTab);b.onkeydown=e=>{const keys=Object.keys(labels).filter(id=>id!=='orders'||RTCRM.get(l.id).status==='client');if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();choose(keys[e.key==='Home'?0:e.key==='End'?keys.length-1:(i+(e.key==='ArrowRight'?1:keys.length-1))%keys.length],true)}}});$('read-full-analysis').onclick=()=>choose('analysis',true);$('read-approach').onclick=()=>choose('approach',true);toolbar.querySelectorAll('button').forEach(b=>b.onclick=()=>{language=b.dataset.language;root.dataset.language=language;toolbar.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});root.dataset.language=language;root.querySelectorAll('[data-copy-approach]').forEach(b=>b.onclick=async()=>{const lang=b.dataset.copyApproach;try{const mail=l.approach.email,plain=mail.subject[lang]+'\n\n'+mail.body[lang];if(mail.paragraphs&&window.ClipboardItem){const tmp=document.createElement('div');tmp.innerHTML=emailContent(mail);const html='<h3>'+esc(mail.subject[lang])+'</h3>'+tmp.querySelector('[lang="'+(lang==='zh'?'zh-CN':'en')+'"]').innerHTML;await navigator.clipboard.write([new ClipboardItem({'text/plain':new Blob([plain],{type:'text/plain'}),'text/html':new Blob([html],{type:'text/html'})})]);}else await navigator.clipboard.writeText(plain);$('approach-copy-status').textContent='已复制 · 未发送 / Copied · Not sent';}catch(e){$('approach-copy-status').textContent='请选中下方邮件文字复制 / Select the email text below to copy';}});choose(selected);RTFlow.footer(l);$('edit-profile').onclick=()=>RTSales.profile(l);if(RTCRM.get(l.id).status==='client')RTSales.mount(l);
 }
 return {mount};
})();
